import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function OtpVerify() {
  const [otp, setOtp] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const mobile = localStorage.getItem("mobile");

  // Redirect if mobile is not set
  useEffect(() => {
    if (!mobile) {
      navigate("/");
    }
  }, [mobile, navigate]);

  const handleVerify = async () => {
    if (!otp.trim()) {
      setMessage("Please enter OTP");
      return;
    }

    setLoading(true);
    setMessage("");

    try {
      const response = await axios.post(
        `http://localhost:8080/otp/verify?mobile=${mobile}&otp=${otp}`
      );
      setMessage(response.data);

      if (response.data.toLowerCase().includes("verified")) {
        // Navigate to Add User page after short delay
        setTimeout(() => navigate("/add-user"), 1000);
      }
    } catch (error) {
      console.error(error);
      setMessage("OTP verification failed. Try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: "20px", maxWidth: "400px", margin: "auto" }}>
      <h2>OTP Verification</h2>
      <p>Mobile: {mobile}</p>

      <input
        type="text"
        placeholder="Enter OTP"
        value={otp}
        onChange={(e) => setOtp(e.target.value)}
        onKeyDown={(e) => e.key === "Enter" && handleVerify()}
        style={{ width: "100%", padding: "8px", margin: "8px 0" }}
      />

      <button
        onClick={handleVerify}
        disabled={loading}
        style={{ width: "100%", padding: "10px", marginTop: "10px" }}
      >
        {loading ? "Verifying..." : "Verify OTP"}
      </button>

      {message && (
        <p style={{ marginTop: "10px", color: "green", fontWeight: "bold" }}>
          {message}
        </p>
      )}
    </div>
  );
}
